function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2, H/2, 20, 0, 2 * Math.PI);
  ctx.stroke();
  for (let i = 0; i < 10; i++) {
    ctx.beginPath();
    ctx.arc(W/2 + Math.sin(t + i) * 50, H/2 + Math.cos(t + i) * 50, 5, 0, 2 * Math.PI);
    ctx.stroke();
  }
  ctx.beginPath();
  ctx.moveTo(W/2, H/2);
  ctx.lineTo(W/2 + Math.sin(t) * 50, H/2 + Math.cos(t) * 50);
  ctx.stroke();
  ctx.beginPath();
  ctx.arc(W/2 + Math.sin(t) * 50, H/2 + Math.cos(t) * 50, 10, 0, 2 * Math.PI);
  ctx.stroke();
  if (Math.sin(t) > 0.5) {
    ctx.beginPath();
    ctx.moveTo(W/2 + Math.sin(t) * 50, H/2 + Math.cos(t) * 50);
    ctx.lineTo(W + 20, H/2);
    ctx.stroke();
  }
  ctx.restore();
}
